template.script:
        
            (function() {
                var vars = {};
                var query = window.location.search.substring(1).split('&');
                for (var i = 0; i < query.length; i++) {
                    var pair = query[i].split('=');
                    vars[pair[0]] = decodeURIComponent(pair[1]);
                }
                var page = parseInt(vars.page, 10);
                var topage = parseInt(vars.topage, 10);
                var sigs = document.getElementsByClassName('l4e-sig-block');
                var footers = document.getElementsByClassName('o_footer_content');

                for (var j = 0; j < sigs.length; j++) {
                    if (!vars.page || page === topage) {
                        sigs[j].style.display = 'block';
                    } else {
                        sigs[j].style.display = 'none';
                    }
                }

                for (var k = 0; k < footers.length; k++) {
                    if (!vars.page || page === topage) {
                        footers[k].style.position = 'static';
                        footers[k].style.bottom = 'auto';
                    } else {
                        footers[k].style.position = 'absolute';
                        footers[k].style.bottom = '-18px';
                        footers[k].style.left = '0px';
                        footers[k].style.right = '0px';
                        footers[k].style.width = '100%';
                    }
                }
            })();
